func (this *CrossChunkCodeMotion_DeclarationStatementGroupCycle) getStatementsLastFirst() *TDeque[*CrossChunkReferenceCollector_TopLevelStatement] {
	var result *TDeque[*CrossChunkReferenceCollector_TopLevelStatement] = newTDeque_(tc_p_CrossChunkReferenceCollector_TopLevelStatement)
	for dsg := range sliceAll_(this.dsgs) {
		var stack1 *TDeque[*CrossChunkReferenceCollector_TopLevelStatement] = tdequeCopy_(tc_p_CrossChunkReferenceCollector_TopLevelStatement, dsg.statementStack)
		var stack2 *TDeque[*CrossChunkReferenceCollector_TopLevelStatement] = result
		result = newTDequeN_(tc_p_CrossChunkReferenceCollector_TopLevelStatement, (stack1.size() + stack2.size()))
		for {
			if stack1.isEmpty() {
				result.asDeque().addAll(Collection(stack2.asDeque()))
				break
			} else if stack2.isEmpty() {
				result.asDeque().addAll(Collection(stack1.asDeque()))
				break
			} else {
				var s1 *CrossChunkReferenceCollector_TopLevelStatement = stack1.peek()
				var s2 *CrossChunkReferenceCollector_TopLevelStatement = stack2.peek()
				if s1.getOriginalOrder() > s2.getOriginalOrder() {
					result.add(stack1.pop())
					if !stack1.isEmpty() && stack1.peek().getOriginalOrder() >= s1.getOriginalOrder() {
						panic(new_IllegalStateException_String(objstr_("Statements are recorded in the wrong order.")))
					}
				} else {
					result.add(stack2.pop())
					if !stack2.isEmpty() && stack2.peek().getOriginalOrder() >= s2.getOriginalOrder() {
						panic(new_IllegalStateException_String(objstr_("Statements are recorded in the wrong order.")))
					}
				}
			}
		}
	}
	return result
}

func (this *CrossChunkCodeMotion_DeclarationStatementGroupCycle) getPreferredChunk(chunksWithImmovableReferences *BitSet) *JSChunk {
	if chunksWithImmovableReferences.isEmpty() {
		return this.currentChunk
	} else if !this.allStatementsCanMove() {
		return this.currentChunk
	} else {
		return this.outer_.graph.getSmallestCoveringSubtree(this.currentChunk, chunksWithImmovableReferences)
	}
}

func (this *CrossChunkCodeMotion_DeclarationStatementGroupCycle) allStatementsCanMove() bool {
	for dsg := range sliceAll_(this.dsgs) {
		if !dsg.allStatementsCanMove() {
			return false
		}
	}
	return true
}

